              BK7258_AUD_ADC_GAIN_MASK | BK7258_AUD_ADC_SAMPLE_EDGE |
              BK7258_AUD_ADC_DIG_MIC_SEL,
              ((uint32_t)cfg->adc_gain << BK7258_AUD_ADC_GAIN_SHIFT) |
              BK7258_AUD_ADC_HPF1_BYPASS | BK7258_AUD_ADC_HPF2_BYPASS);
